type Name = string;
type Pair<T> = [first: T, second?: T];
type Callback = (error: Error | null, value?: number) => void;
type Constructor<T = object> = new (...args: any[]) => T;
type Abstract = abstract new () => object;
type Union = | "a" | "b" | 1 | -1 | 1n | true | null | undefined | void | never;
type Intersection = & A & B;
type Template = `prefix-${string}-${number}px`;
type Indexed = Thing["key"][number];
type Query = typeof import("./module");
type TypeOf = typeof value.member;
type Conditional<T> = T extends string ? "string" : T extends number ? "number" : never;
type Infer<T> = T extends Promise<infer U> ? U : T;
type InferConstraint<T> = T extends [infer H extends string, ...infer R] ? H : never;
type Mapped<T> = { readonly [K in keyof T]+?: T[K] };
type Remapped<T> = { -readonly [K in keyof T as `get${K & string}`]-?: () => T[K] };
type Keys = keyof typeof object;
type Unique = unique symbol;
type Tuple = [string, ...number[], boolean?];
let after = 1;
